-- Run on a NEW Supabase project only. Authoritative grading and roles live here.
create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users on delete cascade, role text not null default 'student' check(role in ('student','teacher')), grade smallint check(grade between 0 and 12), outfit jsonb not null default '{}');
create table public.courses(id text primary key, content jsonb not null);
create table public.units(id text primary key, course_id text references public.courses, content jsonb not null);
create table public.lessons(id text primary key, unit_id text references public.units, content jsonb not null);
create table public.questions(id text primary key, lesson_id text not null references public.lessons, kind text not null, answer text not null, content jsonb not null);
create table public.skill_edges(source text references public.units,target text references public.units,hard_prerequisite boolean not null default false,primary key(source,target));
create table public.question_attempts(id bigint generated always as identity primary key,user_id uuid not null references public.profiles,question_id text not null references public.questions,correct boolean not null,created_at timestamptz not null default now());
create table public.lesson_progress(user_id uuid references public.profiles,lesson_id text references public.lessons,completed_at timestamptz not null default now(),primary key(user_id,lesson_id));
create table public.xp_events(user_id uuid references public.profiles,activity_key text not null,amount integer not null check(amount>0),created_at timestamptz default now(),primary key(user_id,activity_key));
create table public.cosmetic_unlocks(user_id uuid references public.profiles,item_id text,unlocked_at timestamptz default now(),primary key(user_id,item_id));
create table public.classrooms(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 1 and 80),course_id text references public.courses,owner uuid not null references public.profiles,code text not null unique default upper(encode(gen_random_bytes(6),'hex')));
create table public.classroom_memberships(classroom_id uuid references public.classrooms on delete cascade,student_id uuid references public.profiles,primary key(classroom_id,student_id));
create table public.assignments(id uuid primary key default gen_random_uuid(),classroom_id uuid not null references public.classrooms on delete cascade,lesson_id text not null references public.lessons,title text not null check(length(title) between 1 and 120),due_at timestamptz);
create index attempts_user_question on public.question_attempts(user_id,question_id,correct);
create index memberships_student on public.classroom_memberships(student_id,classroom_id);
create index assignments_classroom on public.assignments(classroom_id);
create index classrooms_owner on public.classrooms(owner);
create function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id) values(new.id);return new;end$$;
create trigger user_created after insert on auth.users for each row execute function public.new_profile();
create function public.owns_room(room uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from classrooms where id=room and owner=auth.uid())$$;
create function public.in_room(room uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from classroom_memberships where classroom_id=room and student_id=auth.uid())$$;
do $$declare t text;begin foreach t in array array['profiles','courses','units','lessons','questions','skill_edges','question_attempts','lesson_progress','xp_events','cosmetic_unlocks','classrooms','classroom_memberships','assignments'] loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy own_profile on public.profiles for select to authenticated using(id=auth.uid());
create policy public_courses on public.courses for select using(true);
create policy public_units on public.units for select using(true);
create policy public_lessons on public.lessons for select using(true);
create policy public_edges on public.skill_edges for select using(true);
-- Question answer keys are deliberately never exposed through the Data API.
create policy own_attempts on public.question_attempts for select to authenticated using(user_id=auth.uid());
create policy own_progress on public.lesson_progress for select to authenticated using(user_id=auth.uid());
create policy own_xp on public.xp_events for select to authenticated using(user_id=auth.uid());
create policy own_cosmetics on public.cosmetic_unlocks for select to authenticated using(user_id=auth.uid());
create policy classroom_read on public.classrooms for select to authenticated using(public.owns_room(id) or public.in_room(id));
create policy membership_read on public.classroom_memberships for select to authenticated using(student_id=auth.uid() or public.owns_room(classroom_id));
create policy assignments_read on public.assignments for select to authenticated using(public.owns_room(classroom_id) or public.in_room(classroom_id));
create policy teacher_assign on public.assignments for insert to authenticated with check(public.owns_room(classroom_id) and exists(select 1 from public.profiles where id=auth.uid() and role='teacher'));
create function public.create_classroom(p_name text,p_course text) returns uuid language plpgsql security definer set search_path=public as $$declare room uuid;begin if not exists(select 1 from profiles where id=auth.uid() and role='teacher') then raise exception 'Approved teacher access required';end if;insert into classrooms(name,course_id,owner) values(trim(p_name),p_course,auth.uid()) returning id into room;return room;end$$;
create function public.join_classroom(p_code text) returns void language plpgsql security definer set search_path=public as $$declare room uuid;begin if not exists(select 1 from profiles where id=auth.uid() and role='student') then raise exception 'Student account required';end if;select id into room from classrooms where code=upper(trim(p_code));if room is null then raise exception 'Invalid classroom code';end if;insert into classroom_memberships values(room,auth.uid()) on conflict do nothing;end$$;
create function public.classroom_overview() returns jsonb language sql stable security definer set search_path=public as $$select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'course',c.course_id,'owner',c.owner,'code',case when c.owner=auth.uid() then c.code else '' end,'members',(select coalesce(jsonb_agg(m.student_id),'[]') from classroom_memberships m where m.classroom_id=c.id and (c.owner=auth.uid() or m.student_id=auth.uid())))),'[]') from classrooms c where c.owner=auth.uid() or public.in_room(c.id)$$;
create function public.assignment_report(p_classroom uuid) returns table(student_id uuid,lesson_id text,completed_at timestamptz) language plpgsql stable security definer set search_path=public as $$begin if not public.owns_room(p_classroom) then raise exception 'Access denied';end if;return query select m.student_id,a.lesson_id,p.completed_at from classroom_memberships m join assignments a on a.classroom_id=m.classroom_id left join lesson_progress p on p.user_id=m.student_id and p.lesson_id=a.lesson_id where m.classroom_id=p_classroom;end$$;
create function public.numeric_answer(value text) returns numeric language plpgsql immutable set search_path=public as $$declare parts text[];begin if value !~ '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)([[:space:]]*/[[:space:]]*[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+))?$' then return null;end if;parts=string_to_array(value,'/');if array_length(parts,1)=2 then if parts[2]::numeric=0 then return null;end if;return parts[1]::numeric/parts[2]::numeric;end if;return parts[1]::numeric;exception when others then return null;end$$;
create function public.submit_answer(p_lesson text,p_question text,p_answer text) returns boolean language plpgsql security definer set search_path=public as $$declare q questions;ok boolean;begin if auth.uid() is null then raise exception 'Sign in required';end if;if length(p_answer)>200 then raise exception 'Answer too long';end if;perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||p_lesson,0));select * into q from questions where id=p_question and lesson_id=p_lesson;if not found then raise exception 'Question not found';end if;if q.kind='numeric' then ok=coalesce(abs(numeric_answer(trim(replace(p_answer,'−','-')))-numeric_answer(q.answer))<=0.000001,false);else ok=regexp_replace(lower(replace(p_answer,'−','-')),'[[:space:]*]','','g')=regexp_replace(lower(q.answer),'[[:space:]*]','','g');end if;insert into question_attempts(user_id,question_id,correct) values(auth.uid(),p_question,ok);if not exists(select 1 from questions lq where lq.lesson_id=p_lesson and not exists(select 1 from question_attempts a where a.user_id=auth.uid() and a.question_id=lq.id and a.correct)) then insert into lesson_progress(user_id,lesson_id) values(auth.uid(),p_lesson) on conflict do nothing;insert into xp_events(user_id,activity_key,amount) values(auth.uid(),'lesson:'||p_lesson,50) on conflict do nothing;end if;return ok;end$$;
create view public.topic_mastery with(security_invoker=true) as select user_id,lesson_id,completed_at from public.lesson_progress;
create view public.assignment_submissions with(security_invoker=true) as select a.id assignment_id,p.user_id,p.completed_at from public.assignments a join public.lesson_progress p on p.lesson_id=a.lesson_id;
revoke all on all functions in schema public from public,anon;
grant execute on function public.owns_room(uuid),public.in_room(uuid),public.create_classroom(text,text),public.join_classroom(text),public.classroom_overview(),public.assignment_report(uuid),public.submit_answer(text,text,text) to authenticated;
grant select on public.courses,public.units,public.lessons,public.skill_edges to anon,authenticated;
grant select on public.profiles,public.question_attempts,public.lesson_progress,public.xp_events,public.cosmetic_unlocks,public.classrooms,public.classroom_memberships,public.assignments,public.topic_mastery,public.assignment_submissions to authenticated;
grant insert on public.assignments to authenticated;
